#include <stdio.h>
int main() {
    int n; if (scanf("%d", &n) != 1) return 0;
    long long a[1005];
    for (int i = 0; i < n; i++) scanf("%lld", &a[i]);
    int count = 0;
    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            if (a[i] > a[j]) {
                printf("%lld %lld\n", a[i], a[j]);
                count++;
            }
        }
    }
    printf("%d\n", count);
    return 0;
}

