import sys
def main():
    toks = sys.stdin.read().split()
    if not toks: return
    n = int(toks[0])
    arr = [int(x) for x in toks[1:n+1]]
    lines = []
    for i in range(n):
        for j in range(i + 1, n):
            if arr[i] > arr[j]: lines.append(f"{arr[i]} {arr[j]}")
    lines.append(str(len(lines)))
    print("\n".join(lines))
if __name__ == "__main__": main()

code.JavaScript:
const fs = require("fs");
function main() {
    const toks = fs.readFileSync(0, "utf-8").trim().split(/\s+/);
    if (!toks || toks.length === 0 || toks[0] === "") return;
    const n = parseInt(toks[0], 10);
    const arr = toks.slice(1, n + 1).map(x => BigInt(x));
    const lines = [];
    for (let i = 0; i < n; i++) {
        for (let j = i + 1; j < n; j++) {
            if (arr[i] > arr[j]) lines.push(`${arr[i]} ${arr[j]}`);
        }
    }
    lines.push(lines.length.toString());
    console.log(lines.join("\n"));
}
main();

